import{z as o,x as i,o as e,c as s,q as t,j as B,D as a,d as r,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"风险归因","description":"","frontmatter":{"title":"风险归因","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rk-attribution.md","filePath":"quant/rk-attribution.md","lastUpdated":1791063341000}'),p={name:"quant/rk-attribution.md"};function m(d,E,h,u,_,C){const A=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="风险归因" tabindex="-1">风险归因 <a class="header-anchor" href="#风险归因" aria-label="Permalink to &quot;风险归因&quot;">​</a></h1><div class="epigraph"><p>归因是把总数拆成责任：谁占了组合风险的几成、当日损益对不对得上预测——拆不干净的组合，限额与考核都立在流沙上。</p><footer>—— 据 Litterman, *Hot Spots and Hedges*, 1996；Tasche, *Capital Allocation to Business Units and Sub-Portfolios*, 2008 整理</footer></div><p><a href="/quant/rk-stress-system">上一课</a>用情景库覆盖了分位数之外的世界，但压力与分位数给出的都是总量；总量不能问责——哪本账簿贡献了几成风险、当日损益为什么与预测不符，需要拆解。本课写风险归因与损益归因：前者决定限额与资本的分配，后者是模型健康的前哨。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两类归因被混用是第一错。风险归因问「风险在哪」：分部对组合尾部损失的贡献；损益归因问「钱从哪来」：因子暴露的实现路径。前者拆分布，后者拆路径，算法不同。第二错在拆法：按名义或市值权重把风险比例分摊——与实际贡献无关，对冲账簿还会被记成大风险。第三错是不对账：预测损益与实际损益的差没有台账，「未解释」长期漂移而无人追，模型或数据的问题被平均数淹没。错在哪的后果：风险归因拆错，限额分错桌；损益归因不对账，模型漂移发现不了，下一课的治理就接不到信号。</p><p><span class="marginnote">常见误区：把归因表当成精确到分的会计。尾部贡献是条件期望的估计，窗口一换排名就变；拆到持仓级主要剩抽样噪声。归因用来定方向与问责层级，不用来争小数点后第二位。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险归因用 Euler 分解：对正齐次的风险测度，组合损失可拆成与持仓成比例的分量，使分部贡献之和恰等于总量。对 <a href="/quant/expected-shortfall">Expected Shortfall</a>，尾部条件期望给出自然的形式：</p> \\[\\mathrm{ES}_\\alpha(L)=\\sum_i \\mathrm{ES}_{i,\\alpha},\\qquad \\mathrm{ES}_{i,\\alpha}=-\\mathbb{E}\\big[X_i \\,\\big|\\, L \\ge \\mathrm{VaR}_\\alpha(L)\\big], \\]<p>即「在组合落入尾部的那 \\(1-\\alpha\\) 条情景里，分部 \\(i\\) 平均亏多少」。模拟框架下逐条尾部路径取平均即可算，不追加模型。三个概念分开用：组成贡献（component，份额，用于分摊）、边际贡献（marginal，再加一单位的斜率，用于决策）、增量贡献（incremental，有与无的差，用于准入）。<a href="/quant/fz-marginal-contribution">因子在组合中的边际贡献</a>课已在因子层面算过这些量，本课把它落到机构分部与账簿。损益归因按日对账：预测损益由灵敏度乘因子实现再加 Gamma、Vega 修正构成，与实际损益的差记入未解释项；<a href="/quant/brinson">Brinson 归因</a>那套配置-选择分解只适用线性股权簿，期权簿不适用。</p><p><span class="marginnote">术语翻译：损益归因的「预测损益」就是用昨天的风险传感器（Delta、Gamma、Vega）乘以今天市场实际走了多少，推算「如果模型没错，今天该赚多少」；它与真实盈亏的差就是「未解释项」。它像体重秤的校准码——秤本身准不准，靠每天拿已知重量试一下才知道。</span></p>',11)),(e(),B(l,null,{default:a(()=>[n(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%AF%B9%E5%86%B2%E7%B0%BF%EF%BC%9A%E4%BD%BF%E7%BB%84%E5%90%88%20ES%20%E4%B8%8B%E9%99%8D%202%20%E4%BA%BF%EF%BC%8C%E4%B8%89%E7%A7%8D%E5%8F%A3%E5%BE%84%E6%80%8E%E4%B9%88%E8%AE%B0%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%20M1%5B%22%E7%BB%84%E6%88%90%E8%B4%A1%E7%8C%AE%EF%BC%9A%E2%88%922%20%E4%BA%BF%EF%BC%8C%E7%94%A8%E4%BA%8E%E5%88%86%E6%91%8A%E4%B8%8E%E9%99%90%E9%A2%9D%E9%85%8D%E9%A2%9D%22%5D%0A%20%20Q%20--%3E%20M2%5B%22%E8%BE%B9%E9%99%85%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%86%8D%E5%8A%A0%201%20%E5%85%83%E5%AF%B9%E5%86%B2%E8%83%BD%E7%9C%81%E5%A4%9A%E5%B0%91%20ES%EF%BC%8C%E7%94%A8%E4%BA%8E%E6%89%A9%E7%BC%A9%E5%86%B3%E7%AD%96%22%5D%0A%20%20Q%20--%3E%20M3%5B%22%E5%A2%9E%E9%87%8F%E8%B4%A1%E7%8C%AE%EF%BC%9A%E6%9C%89%E5%AE%83%E4%B8%8E%E6%B2%A1%E5%AE%83%E7%9A%84%E6%80%BB%20ES%20%E4%B9%8B%E5%B7%AE%EF%BC%8C%E7%94%A8%E4%BA%8E%E6%96%B0%E4%B8%9A%E5%8A%A1%E5%87%86%E5%85%A5%22%5D%0A%20%20M1%20--%3E%20W%5B%22%E6%B7%B7%E7%94%A8%E4%B8%80%E5%BC%A0%E8%A1%A8%EF%BC%9A%E6%83%A9%E7%BD%9A%E5%AF%B9%E5%86%B2%E3%80%81%E5%A5%96%E5%8A%B1%E9%9B%86%E4%B8%AD%22%5D%0A%20%20M2%20--%3E%20W%0A%20%20M3%20--%3E%20W%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<p><span class="marginnote">组成与边际可以差出符号：一个对冲分部的组成贡献是负的——它降低了总风险；按正数分摊的表里它「占资源」，按边际看它每加一单位都在省资源。分摊用 component，扩缩决策用 marginal，混用一张表会同时惩罚对冲和奖励集中。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么 Euler 是问责的前提：可加性让每个分部拿到自己那份分散化折价，分部决策之和与总部目标一致——Tasche 证明按组成贡献计费时，各分部在边际收益越过资本成本时扩张，总部利润同时最大化；按独立资本计费则重复收费，惩罚了分散化本身。VaR 在非椭圆分布上不满足次可加性，分量可能不存在或为负，所以归因建立在 ES 上——这是 <a href="/quant/expected-shortfall">Expected Shortfall</a> 课的连贯性在治理层的兑现。未解释损益是前哨信号：持续同号的残差意味着某个因子映射、定价近似或数据口径坏了；把它当噪声平滑掉，等于关掉模型治理的预警线——治理课的持续监测，一半的输入就来自这张对账表。</p><p><span class="marginnote">数字实例：99% ES 是最差 1% 情景的平均损失。若组合一日 ES=1 亿，股票簿在最差的 250 条路径里平均亏 1.2 亿、对冲簿平均赚 0.2 亿，则组成贡献为 1.2 亿与 −0.2 亿，加总恰等于 1 亿——对冲簿在分摊表上是「负占用」。</span></p>',4)),(e(),B(l,null,{default:a(()=>[n(A,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20DIST%5B%22%E7%BB%84%E5%90%88%E6%8D%9F%E5%A4%B1%E5%88%86%E5%B8%83%22%5D%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%E6%83%85%E6%99%AF%E9%9B%86%E5%90%88%22%5D%0A%20%20TAIL%20--%3E%20COMP%5B%22%E5%88%86%E9%83%A8%E7%BB%84%E6%88%90%E8%B4%A1%E7%8C%AE%EF%BC%9A%E5%8A%A0%E6%80%BB%E7%AD%89%E4%BA%8E%E6%80%BB%20ES%22%5D%0A%20%20COMP%20--%3E%20LIMITS%5B%22%E9%99%90%E9%A2%9D%E4%B8%8E%E8%B5%84%E6%9C%AC%E5%88%86%E6%91%8A%22%5D%0A%20%20SENS%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%E4%B8%8E%E5%9B%A0%E5%AD%90%E5%AE%9E%E7%8E%B0%22%5D%20--%3E%20PRED%5B%22%E9%A2%84%E6%B5%8B%E6%8D%9F%E7%9B%8A%22%5D%0A%20%20PRED%20--%3E%20RES%5B%22%E6%9C%AA%E8%A7%A3%E9%87%8A%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20ACT%5B%22%E5%AE%9E%E9%99%85%E6%8D%9F%E7%9B%8A%22%5D%20--%3E%20RES%0A%20%20RES%20--%3E%7C%22%E6%8C%81%E7%BB%AD%E5%90%8C%E5%8F%B7%22%7C%20GOV%5B%22%E6%A8%A1%E5%9E%8B%E6%B2%BB%E7%90%86%EF%BC%9A%E8%A7%A6%E5%8F%91%E5%A4%8D%E9%AA%8C%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Euler 分解要求对齐次性：ES 满足，VaR 一般不满足；用 VaR 归因的机构至少要检查分位外的分量符号。尾部条件贡献对情景窗口敏感，换窗口换排名，归因表要带窗口声明。归因粒度越高噪声越大：分解到账户级尚可，到持仓级主要剩抽样噪声。归因不替代压力：它拆的是当前分布的尾部，情景覆盖的机制不在里面。Brinson 分解与因子暴露管理是另一门课的主题，本课只划清适用域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险归因拆分布（谁贡献尾部），损益归因拆路径（钱从哪来），算法与用途都不同。</li><li>组成贡献按尾部条件期望计算，加总恰等于总 ES；VaR 非次可加，归因宜建在 ES 上。</li><li>三个概念分工：分摊用 component，决策用 marginal，准入用 incremental。</li><li>未解释损益是模型健康的前哨，持续同号的残差必须进入复验流程。</li><li>出处：Litterman, <em>Hot Spots and Hedges</em>, <em>Journal of Portfolio Management</em>, 1996；Tasche, 2008；Rockafellar and Uryasev, <em>Journal of Risk</em>, 2000；连贯性基础见本站 Expected Shortfall 课。</li></ul>',4))])}const S=o(p,[["render",m]]);export{c as __pageData,S as default};
